func astNode(v any) *Node { n, _ := v.(*Node); return n }
func astIsNil(v any) bool { n, ok := v.(*Node); return v == nil || ok && n == nil }

// astKid returns the value of element i of a tuple node's children (nil if there is none).
func astKid(kids []*Node, i int) any {
	if i < len(kids) {
		return unboxNode(kids[i])
	}
	return nil
}
func astInt(v any) int       { i, _ := v.(int); return i }
func astString(v any) string { s, _ := v.(string); return s }
func astBool(v any) bool     { x, _ := v.(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := v.(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := v.(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := v.(bool); ok {
		return &x
	}
	return nil
}

// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free      []T
	next      int
	bootstrap uint8
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew allocates the first three values independently so a later
// published value cannot retain discarded early siblings through a chunk.
// Later values use the original 8-to-256 chunk growth.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		if s.bootstrap < 3 {
			s.bootstrap++
			return new(T)
		}
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice allocates the first nonempty small list independently to keep
// its backing values separate from later published lists of the same type.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		if s.bootstrap == 0 {
			s.bootstrap = 1
			return make([]T, n)
		}
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	trules[11].text = func(p *tparser, start, end int, text string) tval {
		p.stepWork()
		v := astNew(&p.ext.(*tslabs).tNumber)
		*v = Number{Span: Span{start, end}, Text: text}
		return v
	}
}

// tmk_Binary makes a Binary in an action (newStruct in the typed runtime).
func tmk_Binary(c *tctx, final bool, f0 any, f1 any, f2 any) any {
	c.p.stepWork()
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tBinary)
	c.p.stepWork()
	v.Left = tAs[Expr](tpub(f0))
	c.p.stepWork()
	v.Op = tpubMatch(f1)
	c.p.stepWork()
	v.Right = tAs[Expr](tpub(f2))
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	c.p.stepWork()
	spanOf(f0, &first, &start, &end)
	c.p.stepWork()
	spanOf(f1, &first, &start, &end)
	c.p.stepWork()
	spanOf(f2, &first, &start, &end)
	return c.made(v, first, start, end)
}

// tmk_Number makes a Number in an action (newStruct in the typed runtime).
func tmk_Number(c *tctx, final bool, f0 any) any {
	c.p.stepWork()
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tNumber)
	c.p.stepWork()
	v.Text = astString(f0)
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	c.p.stepWork()
	spanOf(f0, &first, &start, &end)
	return c.made(v, first, start, end)
}

// tmk_Unary makes a Unary in an action (newStruct in the typed runtime).
func tmk_Unary(c *tctx, final bool, f0 any, f1 any) any {
	c.p.stepWork()
	a := c.p.ext.(*tslabs)
	v := astNew(&a.tUnary)
	c.p.stepWork()
	v.Op = tpubMatch(f0)
	c.p.stepWork()
	v.X = tAs[Expr](tpub(f1))
	if final {
		v.Span = Span{c.start, c.end}
		return v
	}
	first, start, end := true, 0, 0
	c.p.stepWork()
	spanOf(f0, &first, &start, &end)
	c.p.stepWork()
	spanOf(f1, &first, &start, &end)
	return c.made(v, first, start, end)
}

func tv0(a *tslabs, v any) *TNode[[]*TNode[string]] {
	a.stepWork()
	return tv1(a, v)
}

func tv1(a *tslabs, v any) *TNode[[]*TNode[string]] {
	a.stepWork()
	switch x := v.(type) {
	case *tnode:
		if x.typ == typeTupleValue || x.typ == typeListValue {
			return nil
		}
		out := &TNode[[]*TNode[string]]{Span: x.Span}
		out.Value = tl0(a, x)
		return out
	case *terror:
		return nil
	case tval:
		if x.tstruct() {
			return nil
		}
		s, e := x.tspan()
		text, _ := x.ttext()
		_ = text
		out := &TNode[[]*TNode[string]]{Span: Span{s, e}}
		out.Value = tl0(a, text)
		return out
	}
	return nil
}

func tl0(a *tslabs, v any) []*TNode[string] {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []*TNode[string]{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		a.stepWork()
		out[i] = tv2(a, c)
	}
	return out
}

func tv2(a *tslabs, v any) *TNode[string] {
	a.stepWork()
	switch x := v.(type) {
	case *tnode:
		if x.typ == typeTupleValue || x.typ == typeListValue {
			return nil
		}
		out := &TNode[string]{Span: x.Span}
		return out
	case *terror:
		return nil
	case tval:
		if x.tstruct() {
			return nil
		}
		s, e := x.tspan()
		text, _ := x.ttext()
		_ = text
		out := &TNode[string]{Span: Span{s, e}}
		out.Value = astString(text)
		return out
	}
	return nil
}

// tslabs holds the chunks the typed values of a parse are allocated from.
type tslabs struct {
	control  *workControl
	tBinary  astChunk[Binary]
	tNumber  astChunk[Number]
	tUnary   astChunk[Unary]
	tl0Chunk astChunk[*TNode[string]]
}

func (a *tslabs) setWorkControl(c *workControl) { a.control = c }
func (a *tslabs) stepWork() {
	if workControlsEnabled && a.control != nil {
		a.control.charge(0, 1)
	}
}

// ParseAST parses the input like Parse and returns the result as typed values. If the parse recovered
// from errors, the result is returned together with SyntaxErrors; an Error node where a struct
// type is expected becomes nil.
// It builds the values directly, without the nodes Parse returns.
func ParseAST(input string, opts ...ParseOption) (Expr, error) {
	a := &tslabs{}
	return tparse(trules[0], input, opts, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
}

// ParseRuleAST parses the whole input with the named rule and returns its typed value.
// Recovered values accompany SyntaxErrors. Nil results and failed parses return the selected type's zero value.
// Invalid options and undefined names return nil with an error. Rule result types:
//
//	main: Expr
//	expr: Expr
//	add: Expr
//	term: Expr
//	mul: Expr
//	unary: Expr
//	neg: Expr
//	power: Expr
//	pow: Expr
//	primary: Expr
//	group: Expr
//	number: *Number
//	ws: *TNode[[]*TNode[string]]
func ParseRuleAST(name, input string, opts ...ParseOption) (any, error) {
	o, err := resolveOptions(opts)
	if err != nil {
		return nil, err
	}
	switch name {
	case "main":
		a := &tslabs{}
		return tparseResolved(trules[0], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "expr":
		a := &tslabs{}
		return tparseResolved(trules[1], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "add":
		a := &tslabs{}
		return tparseResolved(trules[2], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "term":
		a := &tslabs{}
		return tparseResolved(trules[3], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "mul":
		a := &tslabs{}
		return tparseResolved(trules[4], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "unary":
		a := &tslabs{}
		return tparseResolved(trules[5], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "neg":
		a := &tslabs{}
		return tparseResolved(trules[6], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "power":
		a := &tslabs{}
		return tparseResolved(trules[7], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "pow":
		a := &tslabs{}
		return tparseResolved(trules[8], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "primary":
		a := &tslabs{}
		return tparseResolved(trules[9], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "group":
		a := &tslabs{}
		return tparseResolved(trules[10], input, o, a, func(v any) Expr { return tAs[Expr](tpub(v)) })
	case "number":
		a := &tslabs{}
		return tparseResolved(trules[11], input, o, a, func(v any) *Number { return tAs[*Number](v) })
	case "ws":
		a := &tslabs{}
		return tparseResolved(trules[12], input, o, a, func(v any) *TNode[[]*TNode[string]] { return tv0(a, v) })
	default:
		return nil, fmt.Errorf("rule %s is not defined", name)
	}
}

